#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    string s;
    cin >> s;
    string t;
    cin >> t;

    bool ok = s.size() == t.size();
    unordered_map<char, char> toT, toS;
    for (size_t i = 0; ok && i < s.size(); i++) {
        if (toT.count(s[i]) && toT[s[i]] != t[i]) ok = false;
        else if (toS.count(t[i]) && toS[t[i]] != s[i]) ok = false;
        else {
            toT[s[i]] = t[i];
            toS[t[i]] = s[i];
        }
    }
    cout << (ok ? "yes" : "no") << "\n";

    return 0;
}

